          xProgress = xProgress < 0 ? 0 : (xProgress > 1 ? 1 : xProgress);
          yProgress = yProgress < 0 ? 0 : (yProgress > 1 ? 1 : yProgress);
          var yAxisEnter = yProgress >= 0 && yProgress <= 1;
          var xAxisEnter = xProgress >= 0 && xProgress <= 1;
          var isEnter = yAxisEnter || xAxisEnter;
