    /**
     * 获取新路由
     * @param el 当前组件El
     * @param tag 标签参数
     * @param pageNum 当前页码参数
     * @returns {String} 新的URL路径
     */
    function refreshRoute(el, tag, pageNum) {
        var basePath = getBasePath(el);
        var baseUrl = window.location.origin + basePath;
        var params = getParams(basePath);
        var paramTag = tag || params[0];
        if(paramTag === 'all' && !pageNum) paramTag = null;
        if(paramTag && !pageNum) pageNum = 1;
        if(!paramTag && pageNum) paramTag = 'all';
        var paramArr = [''];
        if(paramTag) paramArr.push(paramTag);
        if(pageNum) paramArr.push(pageNum);
        var isAuthorMode = window.location.pathname.indexOf('html') > -1;
        var delimiter = isAuthorMode ? '.' : '/';
        var suffix = isAuthorMode ? '.html' : '';
        var paramPath = paramArr.join(delimiter);
        return baseUrl + paramPath + suffix;
    }

    /**
     * 仅更新路由，并保留原参数，页面不刷新
     * @param url 路由URL
     */
    function syncRoute(url) {
      window.history.pushState(
        {},
        window.document.title,
        url
      );
    }

