    /**
     * 获取基础路径
     * @param el 当前组件El
     * @returns {String} 基础路径
     */
    function getBasePath(el) {
      return $(el).find('input[name="basePath"]').val().replace('.html', '');
    }

    /**
     * 获取当前参数
     * @param basePath 基础路径
     * @returns {Array} params
     */
    function getParams(basePath) {
      var paramPath = window.location.pathname.replace(basePath, '');
      var delimiter = paramPath.indexOf('html') > -1 ? '.' : '/';
      return paramPath.replace('.html', '').split(delimiter).slice(1);
    }

    /**
     * 获取当前参数中的页码
     * @param el 当前组件El
     * @returns {Number} pageParam
     */
    function getPageParam(el) {
      var basePath = getBasePath(el);
      var params = getParams(basePath);
      if(params.length < 2) return 1;
      return params[1] * 1;
    }

