(function () {
    var featureContent = $('.feature-container');
    if (featureContent.length === 0) {
        return;
    }
    function productDetailCharacteristieData(showElement) {
        var modeItem = $(showElement).find('#mode').val();
        var charaList = window.$detail.characteristics.list;
        var model = window.$detail.characteristics.model;
        var list = (modeItem == 'automatic' || modeItem == '') ? charaList : JSON.parse($(showElement).find('#manualList').val());
        // 如果是手动就获取当前默认值
        if (modeItem == 'manual') {
            var initSize = _.find(JSON.parse($(showElement).find('#manualList').val()), function (product) {
                return product.productModel === model;
            });
            if (initSize) {
                list = initSize.sizeList;
            } else {
                list = charaList;
            }
        } else {
            list = charaList;
        }
        var vm = {
            isFirstScreen: ko.observable(false),
            featureData: ko.observableArray(list),
            speed: ko.observable(0),
            refreshView: function (model, list) {
                if (modeItem == 'manual') {
                    var currentSize = _.find(JSON.parse($(showElement).find('#manualList').val()), function (product) {
                        return product.productModel === model;
                    });
                    if (currentSize) {
                        vm.featureData(currentSize.sizeList);
                    } else {
                        vm.featureData(list);
                    }
                } else {
                    vm.featureData(list);
                }
                window.lazyLoadImg();
                eachElementShow(showElement);
            }
        };
        ko.applyBindings(vm, showElement);
        
        window.lazyLoadImg();
        window._characteristicsVm = vm;
    }

    function scrollElement() {
        var windowClientHeight = window.innerHeight || document.documentElement.clientHeight;  //可视区域的高度
        var viewProtHeight = $(window).scrollTop();      //滚动的高度
        var firseElementoffSetTop = $(featureContent[0]).offset().top;
        var enterView = firseElementoffSetTop - viewProtHeight;
        if (enterView <= windowClientHeight) {    //判断是否进入可视区域以及超过可视区域
            listenCharacteristicElement();
        }
    }

    function eachElementShow(showElement){
        var windowClientHeight = window.innerHeight || document.documentElement.clientHeight;  //可视区域的高度
        var viewProtHeight = $(window).scrollTop();      //滚动的高度

        var titleBoxEle = $(showElement).find('.title-box');
        var subTitleBoxEle = $(showElement).find('.subtitle-box');
        var featureListBoxEle = $(showElement).find('.feature-box');

        if (titleBoxEle.length > 0) {
            var titleBoxOffsetTop = titleBoxEle.offset().top;
            var titleElement = $(showElement).find('.feature-title');
            titleBoxOffsetTop - viewProtHeight <= windowClientHeight ? titleElement.addClass('add-feature-title-move') : titleElement.removeClass('add-feature-title-move');
        }
        if (subTitleBoxEle.length > 0) {
            var subtitleBoxOffsetTop = subTitleBoxEle.offset().top;
            var subTitleElement = $(showElement).find('.feature-subtitle');
            subtitleBoxOffsetTop - viewProtHeight <= windowClientHeight ? subTitleElement.addClass('add-feature-title-move') : subTitleElement.removeClass('add-feature-title-move');
        }
        if (featureListBoxEle.length > 0) {
            var featureListBoxOffserTop = featureListBoxEle.offset().top;
            var temp = $(showElement).find('.card-content');
            if (temp) {
                if (featureListBoxOffserTop - viewProtHeight <= windowClientHeight) {
                    _.forEach(temp, function (item, index) {
                        $(item).css('transition-delay', index * 0.2 + 's')
                    })
                    temp.addClass('add-feature-title-move');
                }
                else {
                    temp.css('transition-delay', '0s');
                    temp.removeClass('add-feature-title-move');
                }
            }
        }
    }

    function listenCharacteristicElement() {
        _.forEach(featureContent, function (showElement, showIndex) {
            eachElementShow(showElement);
        })
    }

    function initCharacteristics() {
        _.forEach(featureContent, function (showElement, showIndex) {
            var mode = $(showElement).find('#mode').val();
            if (mode == 'automatic' || mode == 'manual' || mode == '') {
                productDetailCharacteristieData(showElement);
            }
        })
        scrollElement();
    }

    window.eventStack &&
        window.eventStack.directive(EVENT_TYPES.SCROLL, 'featureChracteristicInView', function () {
            listenCharacteristicElement();
        });
    
    window.addEventListener('selector-change', function(e) {
      var model = e.data.characteristics.model;
      var list = e.data.characteristics.list;
      window._characteristicsVm && window._characteristicsVm.refreshView(model, list);
    });
    initCharacteristics();
})();

